document.addEventListener("DOMContentLoaded", function () {
  const buttons = Array.from(document.querySelectorAll(".recipe-lightbox-btn"));

  if (buttons.length === 0) return;

  const lightbox = document.createElement("div");
  lightbox.className = "custom-lightbox";

  lightbox.innerHTML = `
    <button type="button" class="lightbox-close" aria-label="Close image">×</button>
    <button type="button" class="lightbox-prev" aria-label="Previous image">‹</button>
    <img class="lightbox-image" src="" alt="Recipe image">
    <button type="button" class="lightbox-next" aria-label="Next image">›</button>
  `;

  document.body.appendChild(lightbox);

  const image = lightbox.querySelector(".lightbox-image");
  const closeBtn = lightbox.querySelector(".lightbox-close");
  const prevBtn = lightbox.querySelector(".lightbox-prev");
  const nextBtn = lightbox.querySelector(".lightbox-next");

  let currentIndex = 0;

  function openLightbox(index) {
    currentIndex = index;
    image.src = buttons[currentIndex].dataset.img;
    lightbox.classList.add("is-open");
  }

  function closeLightbox() {
    lightbox.classList.remove("is-open");
    image.src = "";
  }

  function changeImage(direction) {
    currentIndex += direction;

    if (currentIndex < 0) {
      currentIndex = buttons.length - 1;
    }

    if (currentIndex >= buttons.length) {
      currentIndex = 0;
    }

    image.src = buttons[currentIndex].dataset.img;
  }

  buttons.forEach(function (button, index) {
    button.addEventListener("click", function () {
      openLightbox(index);
    });
  });

  closeBtn.addEventListener("click", closeLightbox);

  prevBtn.addEventListener("click", function () {
    changeImage(-1);
  });

  nextBtn.addEventListener("click", function () {
    changeImage(1);
  });

  lightbox.addEventListener("click", function (event) {
    if (event.target === lightbox) {
      closeLightbox();
    }
  });

  document.addEventListener("keydown", function (event) {
    if (!lightbox.classList.contains("is-open")) return;

    if (event.key === "Escape") closeLightbox();
    if (event.key === "ArrowLeft") changeImage(-1);
    if (event.key === "ArrowRight") changeImage(1);
  });
});